package net.civeira.phylax.feature.observe.observedfingerprintrule.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class PatternVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property pattern of observed fingerprint rule ")
  void test_pattern_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> PatternVO.tryFrom(null));
    Assertions.assertEquals("one", PatternVO.from("one").getPattern());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> PatternVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", PatternVO.from("one").toString());
  }
}
